begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select ok(relrowsecurity,'Private control RLS: '||relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and relname in ('resource_controls','resource_limits','resource_usage','image_processing_leases','generation_execution_leases','asset_paths');
select ok(not has_table_privilege('authenticated','private.'||name,'SELECT,INSERT,UPDATE,DELETE'),'Client cannot access '||name) from unnest(array['resource_controls','resource_limits','resource_usage','image_processing_leases','generation_execution_leases','asset_paths']) name;
select ok(not has_function_privilege('authenticated','private.claim_orphan_path(text,uuid,text)','EXECUTE'),'No client orphan claim');
select ok(not has_function_privilege('authenticated','private.admit_resource(text,uuid)','EXECUTE'),'No direct counter mutation');
select ok(not has_function_privilege('anon','public.admit_image_processing(uuid)','EXECUTE'),'No anonymous processing');
select ok(not prosecdef,'Public image functions are invokers') from pg_proc where oid in ('public.admit_image_processing(uuid)'::regprocedure,'public.release_image_processing(uuid)'::regprocedure);
select set_config('request.jwt.claims','{"role":"authenticated","sub":"11111111-1111-4111-8111-111111111111"}',true);
update private.resource_limits set owner_limit=1 where action in ('story','asset','generation');
set local role authenticated;
select lives_ok($$insert into public.stories(title,child_name,prompt) values('Budget fixture','Nova','A fictional garden')$$,'First story admission');
select lives_ok($$delete from public.stories where title='Budget fixture'$$,'Deletion remains allowed');
select throws_ok($$insert into public.stories(title,child_name,prompt) values('Budget fixture','Nova','A fictional garden')$$,'PT429',null,'Deletion does not reset issuance budget');
select throws_ok($$select * from private.resource_usage$$,'42501',null,'Quota rows are private');
select set_config('test.job',public.enqueue_generation('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2')::text,true);
select is(public.enqueue_generation('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2'),current_setting('test.job')::uuid,'Idempotent enqueue does not consume a second budget');
select lives_ok($$insert into public.assets(story_id,kind,storage_path,mime_type) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2','hero','11111111-1111-4111-8111-111111111111/aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2/12345678-1234-4234-8234-123456789001.webp','image/webp')$$,'First image reservation admitted');
select lives_ok($$delete from public.assets where story_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2'$$,'Empty image reservation removable');
select throws_ok($$insert into public.assets(story_id,kind,storage_path,mime_type) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2','hero','11111111-1111-4111-8111-111111111111/aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2/12345678-1234-4234-8234-123456789002.webp','image/webp')$$,'PT429',null,'Deletion does not reset image issuance');
reset role;
select is((select used from private.resource_usage where action='story' and subject='global'),1,'Rejected request rolled back global counter');
select is((select used from private.resource_usage where action='generation' and subject='global'),1,'Only one generation charged');
select ok((select retired_at is not null from private.asset_paths limit 1),'Deleted metadata retires its path');
update private.resource_limits set owner_limit=20 where action in ('story','asset','generation');
set local role authenticated;
select throws_ok($$insert into public.assets(story_id,kind,storage_path,mime_type) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2','hero','11111111-1111-4111-8111-111111111111/aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2/12345678-1234-4234-8234-123456789001.webp','image/webp')$$,'23505','Image path cannot be reused','Retired path can never be reattached');
select throws_ok($$select public.admit_image_processing('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1')$$,'42501','Image unavailable','Image admission requires ownership');
select set_config('test.lease1',public.admit_image_processing('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1')::text,true);
select set_config('test.lease2',public.admit_image_processing('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1')::text,true);
select throws_ok($$select public.admit_image_processing('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1')$$,'PT429',null,'Only two simultaneous owner image operations');
select lives_ok($$select public.release_image_processing(current_setting('test.lease1')::uuid)$$,'Owner releases lease');
select lives_ok($$select public.release_image_processing(current_setting('test.lease1')::uuid)$$,'Release is idempotent');
reset role;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"22222222-2222-4222-8222-222222222222"}',true);
set local role authenticated;
select lives_ok($$select public.release_image_processing(current_setting('test.lease2')::uuid)$$,'Other owner release reveals nothing');
reset role;
select is((select count(*) from private.image_processing_leases),1::bigint,'Other owner did not release live lease');
update private.image_processing_leases set expires_at=clock_timestamp()-interval '1 second';
select set_config('request.jwt.claims','{"role":"authenticated","sub":"11111111-1111-4111-8111-111111111111"}',true);
set local role authenticated;
select lives_ok($$select public.admit_image_processing('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1')$$,'Expired abandoned lease is reclaimed');
reset role;
select is((select count(*) from private.image_processing_leases),1::bigint,'Expired lease removed');
update private.resource_controls set writes_enabled=false,generation_enabled=false,uploads_enabled=false,images_enabled=false;
set local role authenticated;
select throws_ok($$insert into public.stories(title,child_name,prompt) values('Paused','Nova','Map')$$,'PT503',null,'Emergency pause blocks story writes');
select throws_ok($$select public.admit_image_processing('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1')$$,'PT503',null,'Emergency pause blocks image work');
select is(private.uploads_enabled(),false,'Storage admission sees pause');
select throws_ok($$insert into public.assets(story_id,kind,storage_path,mime_type) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','hero','11111111-1111-4111-8111-111111111111/aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1/12345678-1234-4234-8234-123456789003.webp','image/webp')$$,'PT503',null,'Pause blocks new image reservations');
select is(public.enqueue_generation('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2'),current_setting('test.job')::uuid,'Pause allows reading existing job via idempotent enqueue');
reset role;
insert into private.generation_worker_key values(true,encode(extensions.digest(repeat('a',64),'sha256'),'hex')) on conflict(singleton) do update set key_hash=excluded.key_hash;
select set_config('request.headers',jsonb_build_object('x-generation-worker',repeat('a',64))::text,true);
set local role authenticated;
select throws_ok($$select public.claim_generation(current_setting('test.job')::uuid,'mock')$$,'PT503',null,'Pause blocks worker claim even with capability');
reset role;
update private.resource_controls set writes_enabled=true,generation_enabled=true,uploads_enabled=true,images_enabled=true;
set local role authenticated;
select is(public.claim_generation(current_setting('test.job')::uuid,'mock'),true,'Unpaused worker claims');
select lives_ok($$delete from public.stories where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2'$$,'Delete running story remains allowed');
reset role;
select is((select count(*) from private.generation_execution_leases),1::bigint,'Deleting a story cannot free still-running provider capacity');
select is(private.claim_orphan_path('../unsafe',gen_random_uuid(),'v'),false,'Operator rejects malformed path');
select is(private.claim_orphan_path('11111111-1111-4111-8111-111111111111/aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1/12345678-1234-4234-8234-123456789004.webp',gen_random_uuid(),'v'),false,'Operator refuses missing object');
-- Operator retirement is tested independently of read-only managed Storage metadata.
select is(private.retire_orphan_reservation('11111111-1111-4111-8111-111111111111/aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1/12345678-1234-4234-8234-123456789006.webp','11111111-1111-4111-8111-111111111111'),true,'Operator can atomically retire a previously unissued path');
select set_config('request.jwt.claims','{"role":"authenticated","sub":"11111111-1111-4111-8111-111111111111"}',true);
set local role authenticated;
select throws_ok($$insert into public.assets(story_id,kind,storage_path,mime_type) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','hero','11111111-1111-4111-8111-111111111111/aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1/12345678-1234-4234-8234-123456789006.webp','image/webp')$$,'23505',null,'New metadata cannot win after cleanup retirement');
select lives_ok($$insert into public.assets(story_id,kind,storage_path,mime_type) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','hero','11111111-1111-4111-8111-111111111111/aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1/12345678-1234-4234-8234-123456789007.webp','image/webp')$$,'A fresh owner path still works');
reset role;
select is(private.retire_orphan_reservation('11111111-1111-4111-8111-111111111111/aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1/12345678-1234-4234-8234-123456789007.webp','11111111-1111-4111-8111-111111111111'),false,'Cleanup cannot retire a path after owner reservation wins');
select ok(not has_function_privilege('authenticated','private.retire_orphan_reservation(text,uuid)','EXECUTE'),'Owner cannot invoke operator retirement');
insert into public.stories(owner_id,title,child_name,prompt) select '11111111-1111-4111-8111-111111111111','Capacity fixture','Nova','Map' from generate_series(1,49);
set local role authenticated;
select throws_ok($$insert into public.stories(title,child_name,prompt) values('Over capacity','Nova','Map')$$,'PT429',null,'Current owner library has a separate capacity limit');
reset role;
delete from public.stories where title='Capacity fixture';
insert into private.image_processing_leases(owner_id) select gen_random_uuid() from generate_series(1,8);
set local role authenticated;
select throws_ok($$select public.admit_image_processing('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1')$$,'PT429',null,'Service-wide image concurrency is bounded across owners');
reset role;
-- Global limits apply across accounts, and expired windows never reopen today.
update private.resource_limits set global_limit=1 where action='story';
select set_config('request.jwt.claims','{"role":"authenticated","sub":"22222222-2222-4222-8222-222222222222"}',true);
set local role authenticated;
select throws_ok($$insert into public.stories(title,child_name,prompt) values('Global cap','Leo','Map')$$,'PT429',null,'Global issuance cap applies to a different owner');
reset role;
select set_config('request.jwt.claims','{"role":"authenticated"}',true);
set local role authenticated;
select throws_ok($$select public.admit_image_processing('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb1')$$,'42501',null,'Missing uid denied');
reset role;
select * from finish();
rollback;
